def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    border = []
    for c in range(w):
        border.extend((grid[0][c], grid[h - 1][c]))
    for r in range(1, h - 1):
        border.extend((grid[r][0], grid[r][w - 1]))

    edge_counts = Counter(v for v in border if v != background)
    marker = edge_counts.most_common(1)[0][0]
    target = max(
        (v for v in counts if v != background and v != marker),
        key=lambda v: counts[v]
    )

    # Choose which pair of opposite edges contains the marker bars.
    tb_score = sum(grid[0][c] == marker for c in range(w)) + sum(
        grid[h - 1][c] == marker for c in range(w)
    )
    lr_score = sum(grid[r][0] == marker for r in range(h)) + sum(
        grid[r][w - 1] == marker for r in range(h)
    )

    if tb_score >= lr_score:
        sides = ("top", "bottom")
        length = w

        def side_values(side):
            return grid[0] if side == "top" else grid[h - 1]

        def ray(side, pos):
            dr = 1 if side == "top" else -1
            r, c = (1 if side == "top" else h - 2), pos
            while 0 <= r < h:
                if grid[r][c] == target:
                    out[r][c] = 4
                    break
                out[r][c] = target
                r += dr
    else:
        sides = ("left", "right")
        length = h

        def side_values(side):
            c = 0 if side == "left" else w - 1
            return [grid[r][c] for r in range(h)]

        def ray(side, pos):
            dc = 1 if side == "left" else -1
            r, c = pos, (1 if side == "left" else w - 2)
            while 0 <= c < w:
                if grid[r][c] == target:
                    out[r][c] = 4
                    break
                out[r][c] = target
                c += dc

    # Find contiguous marker bars along each of the two opposite edges.
    bars = {}
    for side in sides:
        vals = side_values(side)
        runs = []
        i = 0
        while i < length:
            if vals[i] != marker:
                i += 1
                continue
            start = i
            while i < length and vals[i] == marker:
                i += 1
            runs.append((start, i - 1))
        bars[side] = runs

    # Target cells aligned with a bar select the corresponding lane offsets.
    active_offsets = set()
    for side in sides:
        for start, end in bars[side]:
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != target:
                        continue
                    pos = c if side in ("top", "bottom") else r
                    if start <= pos <= end:
                        active_offsets.add(pos - start)

    for side in sides:
        for start, end in bars[side]:
            for offset in active_offsets:
                pos = start + offset
                if pos <= end:
                    ray(side, pos)

    return out
